import React, { useContext } from 'react';

import { Variant } from '../types/range-legend.internal.js';

interface RangeLegendVariantContextProps {
  variant: Variant;
}
export const RangeLegendVariantContext =
  React.createContext<RangeLegendVariantContextProps>(
    {} as RangeLegendVariantContextProps,
  );

export const useVariant = () => useContext(RangeLegendVariantContext);
